      "name": "witt_structure_prop",
      "type": " (p : ℕ) {R : Type u_1} {idx : Type u_2} [CommRing R] [hp : Fact (Nat.Prime p)] (Φ : MvPolynomial idx ℤ) (n : ℕ) : (MvPolynomial.aeval fun i => (MvPolynomial.map (Int.castRingHom R)) (wittStructureInt p Φ i)) (wittPolynomial p ℤ n) = (MvPolynomial.aeval fun i => (MvPolynomial.rename (Prod.mk i)) (wittPolynomial p R n)) Φ",
      "module": "Mathlib.RingTheory.WittVector.StructurePolynomial"
    },
    {
      "name": "C_p_pow_dvd_bind₁_rename_wittPolynomial_sub_sum",
      "type": " {p : ℕ} {idx : Type u_2} [hp : Fact (Nat.Prime p)] (Φ : MvPolynomial idx ℤ) (n : ℕ) (IH : ∀ m < n, (MvPolynomial.map (Int.castRingHom ℚ)) (wittStructureInt p Φ m) = wittStructureRat p ((MvPolynomial.map (Int.castRingHom ℚ)) Φ) m) : MvPolynomial.C ↑(p ^ n) ∣ (MvPolynomial.bind₁ fun b => (MvPolynomial.rename fun i => (b, i)) (wittPolynomial p ℤ n)) Φ - ∑ i ∈ Finset.range n, MvPolynomial.C (↑p ^ i) * wittStructureInt p Φ i ^ p ^ (n - i)",
      "module": "Mathlib.RingTheory.WittVector.StructurePolynomial"
    },
    {
      "name": "bind₁_rename_expand_wittPolynomial",
      "type": " {p : ℕ} {idx : Type u_2} [hp : Fact (Nat.Prime p)] (Φ : MvPolynomial idx ℤ) (n : ℕ) (IH : ∀ m < n + 1, (MvPolynomial.map (Int.castRingHom ℚ)) (wittStructureInt p Φ m) = wittStructureRat p ((MvPolynomial.map (Int.castRingHom ℚ)) Φ) m) : (MvPolynomial.bind₁ fun b => (MvPolynomial.rename fun i => (b, i)) ((MvPolynomial.expand p) (wittPolynomial p ℤ n))) Φ = (MvPolynomial.bind₁ fun i => (MvPolynomial.expand p) (wittStructureInt p Φ i)) (wittPolynomial p ℤ n)",
